target = ""
for c in names:
    if counts[c] == min_count and target == "":
        target = c
target_members = members[target]
missing = ask(value={"all_users": all_users, "channel_members": target_members}, question="Return the usernames in 'all_users' that are NOT in 'channel_members'.", type="list[str]")
for u in missing:
    add_user_to_channel(user=u, channel=target)
