channels = get_channels()
users = []
counts = {}
for ch in channels:
    members = get_users_in_channel(channel=ch)
    for u in members:
        if u not in users:
            users.append(u)
for ch in channels:
    msgs = read_channel_messages(channel=ch)
    authors = ask(value=msgs, question="Return the username of the author of each message, one entry per message, in the same order as the messages. Include every message.", type="list[str]")
    for a in authors:
        if a not in users:
            users.append(a)
        if a in counts:
            counts[a] = counts[a] + 1
        else:
            counts[a] = 1
for u in users:
    if u not in counts:
        counts[u] = 0
entries = [[-counts[u], u] for u in users]
ordered = sorted(entries)
report = ""
for i in range(len(ordered)):
    k = i + 1
    name = ordered[i][1]
    send_direct_message(recipient=name, body="Congrats on being the " + str(k) + "-th most active user!")
    report = report + str(k) + ". " + name + " (" + str(counts[name]) + " messages)\n"
respond(text="Sent congratulations to " + str(len(ordered)) + " users. Ranking:\n" + report)

channels_raw = get_channels()
