users = []
counts = {}
for ch in channel_names:
    members_raw = get_users_in_channel(channel=ch)
    members = ask(value=members_raw, question="List the usernames of all users in this channel.", type="list[str]")
    for m in members:
        if m not in users:
            users = users + [m]
    msgs_raw = read_channel_messages(channel=ch)
    authors = ask(value=msgs_raw, question="For each message in this channel, give the username of its author, one entry per message, in order. Include duplicates.", type="list[str]")
    for a in authors:
        if a not in users:
            users = users + [a]
        if a in counts:
            counts[a] = counts[a] + 1
        else:
            counts[a] = 1
for u in users:
    if u not in counts:
        counts[u] = 0
pairs = [(-counts[u], u) for u in users]
ranked = sorted(pairs)
summary = ""
for i in range(len(ranked)):
    name = ranked[i][1]
    ordinal = ask(value=i + 1, question="Return the English ordinal form of this integer, such as 1st, 2nd, 3rd, 4th, 11th, 21st.", type="str")
    send_direct_message(recipient=name, body="Congrats on being the " + ordinal + " most active user!")
